func (c *GitHubClient) enforceFileShrinkFloor(ctx context.Context, owner, repo, branch string, files map[string]interface{}, floor float64) error {
	if _, enabled := clampShrinkFloor(floor); !enabled { return nil }
	for path, fileData := range files {
		newBytes, err := incomingFileBytes(fileData)   // base64 measured DECODED
		if err != nil { return fmt.Errorf("%s: %w", shrinkMeasurementErrorFix, err) }
