type GitCommitData struct {
	RepoName      string                 `json:"repo_name"`
	Domain        string                 `json:"domain"`
	Files         map[string]interface{} `json:"files"`
	Deletions     []string               `json:"deletions,omitempty"`
	CommitMessage string                 `json:"commit_message"`
	Branch        string                 `json:"branch,omitempty"`

	// FileShrinkFloor opts this commit into the shrink guard (bugs_open/198):
	// refuse the commit if any file already >= minShrinkGuardFileBytes would be
	// replaced by less than this fraction of its current bytes. Zero means OFF.
	FileShrinkFloor float64 `json:"file_shrink_floor,omitempty"`
}

const gitFileShrinkFloorKey = "file_shrink_floor"

func shrinkFloorForGitData(config map[string]interface{}) (float64, bool) {
	floor, present := pruneFloorFromConfig(config, gitFileShrinkFloorKey, 0)
	if !present || floor <= 0 {
		return 0, false
	}
	return floor, true
}

